)

// pdfcpu keeps its config path in a package level variable, so it is disabled once
// at startup instead of on every request to avoid concurrent writes.
func init() {
	pdfmodel.ConfigPath = "disable"
}

// defaultMaxConcurrentJobs is the fallback used when the caller did not configure
// a job concurrency limit, so a Service is never built with an unbounded runner.
const defaultMaxConcurrentJobs = 4

// defaultMaxConcurrentSync plays the same role for synchronous masking: a zero
// sized slot pool would block every request forever, so it is never built.
const defaultMaxConcurrentSync = 4

type Service struct {
	config   config.Config
	client   *upstage.Client
	jobStore *jobs.Store
	// jobSlots bounds how many queued jobs run at once. Waiting runners hold no
	// document bytes, because each one reads its input back from disk only after
	// it acquires a slot.
	jobSlots chan struct{}
	// syncSlots bounds how many synchronous masks decode and re-render a document at
	// once. Rendering a page costs many times the upload size, so without this the
	// job limit could be bypassed entirely by calling /v1/mask instead.
	syncSlots chan struct{}
	// syncQueueWait is how long a synchronous request waits for a free slot before it
	// is told the server is busy. Zero rejects it right away.
	syncQueueWait time.Duration
	// jobRetention is how long a finished job keeps its stored files. Zero keeps them.
	jobRetention time.Duration
	// draining is closed once the service starts stopping. A job that has not claimed
	// a slot yet gives up instead of starting work the process has no time to finish.
	draining chan struct{}
	// drainMu keeps a runner from being registered after Shutdown started waiting for
	// the registered ones.
	drainMu sync.RWMutex
	// runners tracks the job goroutines that are still masking a document, so a
	// graceful stop can wait for them instead of discarding nearly finished work.
	runners sync.WaitGroup
}

type ProcessInput struct {
	Attachment document.Attachment
	Options    upstage.ParseOptions
}

// InvalidInputError marks an upload that is rejected before any work is queued or persisted.
type InvalidInputError struct {
	Err error
}

// ServerBusyError marks a synchronous request that gave up waiting for a free
// processing slot. Shedding it is what keeps a burst of uploads from rendering
// every document at the same time.
type ServerBusyError struct {
	Limit int
}

func (e *ServerBusyError) Error() string {
	return fmt.Sprintf("server is already masking %d documents", e.Limit)
}

func (e *InvalidInputError) Error() string {
	return e.Err.Error()
}

func (e *InvalidInputError) Unwrap() error {
	return e.Err
}

// unrecognizedPayloadError marks a 200 response from the inference endpoint whose
// body could not be turned into fields to mask. It is reported as an upstream
// failure, never as a clean document, because the two are indistinguishable from
// the downloaded file alone.
type unrecognizedPayloadError struct {
	detail string
}

func (e *unrecognizedPayloadError) Error() string {
	return "upstream response could not be interpreted as PII fields: " + e.detail
}

func New(cfg config.Config, client *upstage.Client, jobStore *jobs.Store) *Service {
	slots := cfg.Limits.MaxConcurrentJobs
	if slots <= 0 {
		slots = defaultMaxConcurrentJobs
	}
	syncSlots := cfg.Limits.MaxConcurrentSync
	if syncSlots <= 0 {
		syncSlots = defaultMaxConcurrentSync
	}
	return &Service{
		config:        cfg,
		client:        client,
		jobStore:      jobStore,
		jobSlots:      make(chan struct{}, slots),
		syncSlots:     make(chan struct{}, syncSlots),
		syncQueueWait: cfg.Limits.SyncQueueWait,
		jobRetention:  cfg.Storage.JobRetention,
		draining:      make(chan struct{}),
	}
}

// Shutdown stops starting new job runners and waits for the ones already masking a
// document to finish, so a restart does not throw away work that was nearly done.
// Async jobs outlive the request that queued them, so draining the HTTP server does
// not cover them. It returns ctx.Err() if the deadline passes first; whatever was
// still running then stays marked running and is reported as interrupted on the
// next start.
func (s *Service) Shutdown(ctx context.Context) error {
	s.drainMu.Lock()
	select {
	case <-s.draining:
	default:
		close(s.draining)
	}
	s.drainMu.Unlock()

	finished := make(chan struct{})
	go func() {
		s.runners.Wait()
		close(finished)
	}()
	select {
	case <-finished:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// StartRetentionSweeper deletes stored uploads and masked outputs once they are older
// than the configured retention window, so the documents the service was asked to mask
// do not sit on disk forever. It returns immediately, and does nothing at all when
// retention is disabled.
func (s *Service) StartRetentionSweeper(ctx context.Context) {
	if s.jobRetention <= 0 {
		return
	}
	go s.runRetentionSweeper(ctx, retentionSweepInterval(s.jobRetention))
}

func (s *Service) runRetentionSweeper(ctx context.Context, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		if deleted, err := s.PurgeExpiredJobs(time.Now().UTC()); err != nil {
			log.Printf("job retention sweep failed: %v", err)
		} else if len(deleted) > 0 {
			log.Printf("job retention sweep removed %d expired job(s)", len(deleted))
		}
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
	}
}

// PurgeExpiredJobs drops the jobs that are past the retention window right now.
func (s *Service) PurgeExpiredJobs(now time.Time) ([]string, error) {
	if s.jobRetention <= 0 {
		return nil, nil
	}
	return s.jobStore.DeleteExpired(now.Add(-s.jobRetention))
}

// retentionSweepInterval keeps expired files from lingering long past their deadline
// without waking the sweeper up more often than the window itself warrants.
func retentionSweepInterval(retention time.Duration) time.Duration {
	interval := retention / 4
	if interval < time.Minute {
		return time.Minute
	}
	if interval > time.Hour {
		return time.Hour
	}
	return interval
}

func (s *Service) ProcessSync(ctx context.Context, input ProcessInput) (*core.ProcessMetadata, []byte, error) {
	requestID := uuid.NewString()
	release, err := s.acquireSyncSlot(ctx)
	if err != nil {
		return rejectedSyncMetadata(requestID, input, err), nil, err
	}
	defer release()
	return s.process(ctx, requestID, input)
}

// acquireSyncSlot reserves one of the synchronous masking slots and returns the
// function that gives it back. A short queue absorbs a burst; past that the caller
// is shed with a ServerBusyError instead of piling another rendered document into
// memory alongside the ones already in flight.
func (s *Service) acquireSyncSlot(ctx context.Context) (func(), error) {
	release := func() { <-s.syncSlots }
	select {
	case s.syncSlots <- struct{}{}:
		return release, nil
	default:
	}
	if s.syncQueueWait <= 0 {
		return nil, &ServerBusyError{Limit: cap(s.syncSlots)}
	}

	timer := time.NewTimer(s.syncQueueWait)
	defer timer.Stop()
	select {
	case s.syncSlots <- struct{}{}:
		return release, nil
	case <-timer.C:
		return nil, &ServerBusyError{Limit: cap(s.syncSlots)}
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

// rejectedSyncMetadata describes a request that never started, so the caller still
// gets the same metadata shape it would get for a failure during processing.
func rejectedSyncMetadata(requestID string, input ProcessInput, err error) *core.ProcessMetadata {
	now := time.Now().UTC()
	apiErr := &core.APIError{
		Code:      "request_canceled",
		Message:   "요청이 취소되었습니다.",
		Detail:    err.Error(),
		Retryable: false,
	}
	var busy *ServerBusyError
	if errors.As(err, &busy) {
		apiErr = &core.APIError{
			Code:      "server_busy",
			Message:   "처리 중인 요청이 많아 지금은 마스킹을 시작할 수 없습니다. 잠시 후 다시 시도해 주세요.",
			Detail:    err.Error(),
			Retryable: true,
		}
	}
	return &core.ProcessMetadata{
		RequestID: requestID,
		Status:    "failed",
		Input: core.FileDescriptor{
			FileName: input.Attachment.Name,
			MIMEType: input.Attachment.MIMEType,
			Size:     input.Attachment.Size,
		},
		MaskPolicy: core.MaskPolicy{
			Mode:           "selective-redaction",
			SupportedRules: masking.SupportedRuleNames(),
		},
		Error:     apiErr,
		CreatedAt: now,
		UpdatedAt: now,
	}
}

